const c=()=>({getYouTubeID:t=>{if(!t)return null;const e=/^.*(youtu.be\/|v\/|u\/\w\/|embed\/|watch\?v=|&v=)([^#&?]*).*/,r=t.match(e);return r&&r[2].length===11?r[2]:null},copyToClipboard:async t=>{try{return await navigator.clipboard.writeText(t),!0}catch(e){return console.error("Failed to copy:",e),!1}},formatDate:t=>new Date(t).toLocaleDateString("id-ID",{year:"numeric",month:"long",day:"numeric"})});export{c as u};
